"import fs from 'fs';

const base = 'C:/Users/Administrator/.gemini/antigravity/brain/4c2e6fae-176b-4c19-b6ee-624ce2ade958/scratch';
const txt = fs.readFileSync(`${base}/protel_netlist.net`, 'utf8');
const lines = txt.split(/\r?\n/);
const comps = {};
const nets = [];
let i = 0;
while (i < lines.length) {
  if (lines[i] === '[') {
    let des = '', part = '';
    i++;
    while (i < lines.length && lines[i] !== ']') {
      if (lines[i] === 'DESIGNATOR') des = lines[++i];
      else if (lines[i] === 'PARTTYPE') part = lines[++i];
      i++;
    }
    if (des) comps[des] = part;
  } else if (lines[i] === '(') {
    i++;
    const netName = lines[i++];
    const pins = [];
    while (i < lines.length && lines[i] !== ')') {
      if (lines[i].trim()) pins.push(lines[i].trim());
      i++;
    }
    nets.push({ netName, pins });
  }
  i++;
}

const u1Nets = [];
for (const n of nets) {
  const u1p = n.pins.filter(p => p.startsWith('U1-'));
  if (u1p.length) {
    u1Nets.push({ net: n.netName, u1: u1p, others: n.pins.filter(p => !p.startsWith('U1-')) });
  }
}

fs.writeFileSync(`${base}/parsed_netlist.json`, JSON.stringify({ comps, u1Nets, nets }, null, 2));
console.log(`Total comps: ${Object.keys(comps).length}, Total nets: ${nets.length}, U1 nets: ${u1Nets.length}`);
for (const x of u1Nets) {
  console.log(`${x.u1.join(',')} -> ${x.net} | ${x.others.slice(0, 10).join(', ')}`);
}
"

