26: void HMI_SendCmd(const char *cmd)
27: {
28:     const uint8_t end[3] = {0xFF,0xFF,0xFF};
29:     int i;
30:     while (*cmd) {
31:         while (USART_GetFlagStatus(USART3, USART_FLAG_TC) == RESET);
