33:     }
34:     for (i = 0; i < 3; i++) {
35:         while (USART_GetFlagStatus(USART3, USART_FLAG_TC) == RESET);
36:         USART_SendData(USART3, end[i]);
37:     }
38:     Delay_ms(10);
39: }
