90: void HMI_RxCallback(uint8_t *data, uint16_t len)
91: {
92:     uint8_t ctrl, event;
93:     if (len < 6 || data[0] != 0x65) return;
94: 
95:     ctrl  = data[2];
96:     event = data[3];
97: 
98:     if (event != 0x00) return;
99: 
100:     switch (ctrl) {
101:     case 1:  Therapy_OnMainModeSelected(MODE_BREATH); break;
102:     case 2:  Therapy_OnMainModeSelected(MODE_STIM);   break;
103:     case 3:  Therapy_OnMainModeSelected(MODE_COMBO);  break;
104:     case 4:  Therapy_OnBreathSubSelected(BREATH_SIMPLE); break;
105:     case 5:  Therapy_OnBreathSubSelected(BREATH_BIO);    break;
106:     case 6:  Therapy_OnWaveSelected(WAVE_CONT);          break;
107:     case 7:  Therapy_OnWaveSelected(WAVE_INTERMITTENT);  break;
108:     case 8:  Therapy_OnWaveSelected(WAVE_DENSE_SPARSE);  break;
109:     case 10: Therapy_OnStartStop(); break;
110:     case 11: Therapy_OnReturn();    break;
111:     case 12: Therapy_OnSettings();  break;
112:     default: break;
113:     }
114: }

