"#ifndef __BSP_SCREEN_H
#define __BSP_SCREEN_H

#include "main.h"

#ifdef __cplusplus
extern "C" {
#endif

/* ============================================================================
 * TJC Serial Screen Protocol Definition (USART3: PB10/TX, PB11/RX, 115200 8N1)
 *
 * 1. MCU -> Screen: ASCII command + 3-byte trailer (0xFF 0xFF 0xFF)
 *    Example: "lung.val=65\xFF\xFF\xFF"  "page running\xFF\xFF\xFF"
 *
 * 2. Screen -> MCU: Binary frame + 3-byte trailer (0xFF 0xFF 0xFF)
 *    - Custom Control Frame (FPM compatible):
 *      [0x05] [page] [control] [value] [extra...] [0xFF 0xFF 0xFF]
 *    - Native TJC Touch Return Frame:
 *      [0x65] [page] [comp_id] [event] [0xFF 0xFF 0xFF]
 *    - Native TJC Numeric Return Frame:
 *      [0x71] [b0] [b1] [b2] [b3] [0xFF 0xFF 0xFF]
 * ========================================================================== */

#define SCREEN_FRAME_HDR_CTRL   0x05U
#define SCREEN_FRAME_HDR_TOUCH  0x65U
#define SCREEN_FRAME_HDR_PAGE   0x66U
#define SCREEN_FRAME_HDR_STR    0x70U
#define SCREEN_FRAME_HDR_NUM    0x71U

#define SCREEN_FRAME_MAX_DATA   48U

/* Page IDs used in 0x05 [page] [control] [value] protocol */
typedef enum {
    SCREEN_PAGE_START       = 0x00U, /* Main menu: Breath / Stim / Combo */
    SCREEN_PAGE_BREATH_SEL  = 0x01U, /* Breath submode: Simple / Biofeedback */
    SCREEN_PAGE_STIM_SEL    = 0x02U, /* Stim wave: Cont / Intermittent / Dense-Sparse */
    SCREEN_PAGE_TREAT_RUN   = 0x03U, /* Treatment ready/running/paused screen */
    SCREEN_PAGE_SETTINGS    = 0x04U, /* Settings: Volume / Timer / BLE */
    SCREEN_PAGE_END         = 0x05U  /* Treatment finished summary */
} ScreenPageId_t;

typedef struct {
    uint8_t header;
    uint8_t page;
    uint8_t control;
    uint8_t value;
    uint8_t raw[SCREEN_FRAME_MAX_DATA];
    uint8_t len;
} ScreenFrame_t;

