#define SCREEN_RX_RING_SIZE     256U

/* Lock-free SPSC ring buffer: ISR writes s_rx_head, ScreenTask reads s_rx_tail */
static uint8_t           s_rx_ring[SCREEN_RX_RING_SIZE];
static volatile uint16_t s_rx_head = 0U;
static volatile uint16_t s_rx_tail = 0U;
static volatile uint32_t s_rx_overflow_cnt = 0U;
static uint8_t           s_rx_byte_it = 0U;

