    if (tracks == NULL || count == 0U) return;
    if (count > AUDIO_QUEUE_MAX) count = AUDIO_QUEUE_MAX;

    s_queue_cnt  = 0U;
    s_queue_tail = 0U;

    for (i = 0U; i < count; i++)
    {
        s_play_queue[i] = tracks[i];
    }
    s_queue_cnt  = count;
    s_queue_tail = 0U;

    BSP_Audio_PlayTrack(s_play_queue[0]);
    s_track_play_tick = HAL_GetTick();
    s_busy_prev = 1U;
}

