451:  * @note   1. 持续从环形缓冲区提取完整帧并进入三级 switch-case 分发
452:  *         2. 治疗运行期按需节流刷新肺部动画（0~100）与剩余倒计时
453:  *         3. 每 10 秒刷新一次电池电量图标
454:  * @param  argument: FreeRTOS 任务参数（未使用）
455:  * @retval 无
456:  */
457: void ScreenTask(void const *argument)
458: {
459:     ScreenFrame_t frame;
460:     uint32_t tick_cnt = 0U;
461:     uint8_t  last_lung = 255U;      /* 上次已发送的肺部进度，用于变化检测节流 */
462:     uint16_t last_remain_s = 0xFFFFU;
463:     (void)argument;
464: 
465:     osDelay(50U);
466: 
467:     /* 启动初期显式关闭屏幕休眠与自动休眠定时器，确保屏幕始终常亮不熄屏 */
468:     BSP_Screen_SendRawCmd("sleep=0");
469:     BSP_Screen_SendRawCmd("usleep=0");
470: 
471:     for (;;)
472:     {
473:         /* 1. 排空并解析所有以 0xFF 0xFF 0xFF 结尾的完整上行数据帧 */
474:         while (BSP_Screen_ReadFrame(&frame))
475:         {
476:             if (frame.header == SCREEN_FRAME_HDR_CTRL || frame.header == SCREEN_FRAME_HDR_CUSTOM)
477:             {
478:                 if (frame.len >= 3U)
479:                 {
480:                     Screen_HandleCtrlFrame(&frame);
481:                 }
482:             }
483:             else if (frame.header == SCREEN_FRAME_HDR_TOUCH) /* 淘晶驰原生触摸帧兜底：0x65 [page] [comp] [event] */
484:             {
485:                 if (frame.len >= 4U)
486:                 {
487:                     Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
488:                 }
489:             }
490:         }
491: 
492:         /* 2. 治疗运行中定时刷新肺部动画与剩余时间（值变化时才发送，降低串口负载） */
493:         if (g_app.running && !g_app.paused)
494:         {
495:             if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
496:             {
497:                 last_lung = g_app.lung_pct;
498:                 BSP_Screen_SetLungFill(last_lung);
499:             }
500: 
501:             if ((tick_cnt % 10U) == 0U) /* 每 200 ms 检查一次倒计时秒数变化 */
502:             {
503:                 uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
504:                 uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
505:                 uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
506:                 if (rem_s != last_remain_s)
507:                 {
508:                     last_remain_s = rem_s;
509:                     BSP_Screen_SetRemainTimeSec(rem_s);
510:                 }
511:             }
512:         }
513:         else
514:         {
515:             last_lung = 255U;
516:             last_remain_s = 0xFFFFU;
517:         }
518: 
519:         /* 3. 每 10 s（500 * 20 ms）刷新一次电量显示 */
520:         if ((tick_cnt % 500U) == 0U)
521:         {
522:             BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
523:         }
524: 
525:         tick_cnt++;
526:         osDelay(20U);
527:     }
528: }

