    const char *pname = NULL;

    if (s_current_screen_page == SCREEN_PAGE_JIANYI)          pname = "jianyi";
    else if (s_current_screen_page == SCREEN_PAGE_JIANYIELEC)  pname = "jianyielec";
    else if (s_current_screen_page == SCREEN_PAGE_FANKUI)      pname = "fankui";
