        BSP_Screen_SendRawCmd(cmd);
    }
    else
    {
        /* 全部隐藏 */
        snprintf(cmd, sizeof(cmd), "vis %s.p1,0", pname);
        BSP_Screen_SendRawCmd(cmd);
        snprintf(cmd, sizeof(cmd), "vis %s.p2,0", pname);
        BSP_Screen_SendRawCmd(cmd);
    }
}"

